"""Edge-heavy fuzz: narrow alphabets, equality boundaries, bigger capacities."""
import json, random, sys, copy
sys.path.insert(0, '/workspace/tmp/dev')
sys.path.insert(0, '/workspace/site')
sys.path.insert(0, '/workspace/submission')
import harness, reference, gen

NARROW = [0, 1513, 1514, 1515, 3028]
TINY = [1513, 1515]

def norm(obj):
    return json.dumps(obj, sort_keys=True, separators=(',', ':'))

def gen_request(rng):
    nrel = rng.randint(1, 2)
    releases = []
    for i in range(nrel):
        classes = rng.randint(1, 3)
        width = rng.randint(2, 4)
        spec = gen.gen_release(rng, 'm%d' % i, classes, width)
        alph = rng.choice([NARROW, TINY, gen.ALPHABET])
        for group in ('discovery', 'train', 'validation'):
            for row in spec[group]:
                if rng.random() < 0.8:
                    n = len(row['values'])
                    row['values'] = [rng.choice(alph) for _ in range(n)]
        spec['eps'] = [rng.randint(0, 2), 1]
        spec['ratio'] = rng.choice([[0, 1], [1, 1], [1, 2], [2, 2]])
        spec['threshold'] = [rng.randint(0, 3), 1]
        releases.append(spec)
    capacity = {'range': rng.randint(0, 6), 'exact': rng.randint(0, 6)}
    blocks = []
    ops = []
    active = set()
    current = None
    last_ts = {}
    fpool = ['f%d' % i for i in range(rng.randint(1, 3))]
    for _ in range(rng.randint(0, 30)):
        kind = rng.choice(['install', 'open', 'packet', 'close', 'packet', 'close'])
        if kind == 'install':
            ops.append(['install', rng.choice(releases)['id']])
        elif kind == 'open':
            fid = rng.choice(fpool)
            if current is not None and fid not in active:
                ops.append(['open', fid]); active.add(fid); last_ts[fid] = 0
        elif kind == 'packet':
            if active:
                fid = rng.choice(sorted(active))
                ts = last_ts[fid] + rng.randint(0, 2)
                last_ts[fid] = ts
                ops.append(['packet', fid, ts, rng.randint(0, 1), rng.choice([1, 2, 100, 1514])])
        else:
            if active:
                fid = rng.choice(sorted(active))
                ops.append(['close', fid]); active.discard(fid)
        if ops and rng.random() < 0.4:
            blocks.append(ops); ops = []
    for fid in sorted(active):
        ops.append(['close', fid])
    if ops:
        blocks.append(ops)
    if not blocks:
        blocks = [[]]
    return {'capacity': capacity, 'releases': releases, 'blocks': blocks}

def main():
    seed0 = int(sys.argv[1]); count = int(sys.argv[2])
    hp = harness.InProcess()
    from formats import validate, unique, constant
    fails = 0
    for k in range(count):
        rng = random.Random(seed0 + k)
        req = gen_request(rng)
        data = json.dumps(req, separators=(',', ':')).encode()
        parsed = json.loads(data.decode(), object_pairs_hook=unique, parse_constant=constant)
        validate(parsed)
        out = hp.run(data)
        ref = reference.response(copy.deepcopy(req))
        if norm(json.loads(out)) != norm(ref):
            fails += 1
            print('MISMATCH seed', seed0 + k)
            open('/workspace/tmp/dev/fail2_%d.json' % (seed0 + k), 'wb').write(data)
            if fails >= 3:
                break
    print('done, fails =', fails)

main()
